type DeleteProjectProps = {
  onConfirm: () => void;
  projectName?: string;
};

export default function DeleteProject({ onConfirm, projectName }: DeleteProjectProps) {
  const [open, setOpen] = useState(false);

  const close = () => setOpen(false);

  const handleConfirm = () => {
    close();
    onConfirm();
  };

  return (
    <>
